package view

import (
	"fmt"
	"path"
	"strings"

	"github.com/flintcraftstudio/standard-template/internal/assets"
)

// imgResponsiveWidths are the widths generated by the optimize-images pass
// for full-bleed and gallery images, as AVIF and WebP. (There are no JPG
// widths: the base JPG is the single <img> fallback for browsers that take
// neither format.) Sources narrower than 1600px have their widest variants
// upscaled so every width exists.
var imgResponsiveWidths = []int{400, 800, 1200, 1600}

// imgFocus is the object-position for images whose subject sits off-centre
// in the crop they're shown at. object-cover crops a 16:9 hero hard on a
// portrait phone (the 68vh detail hero shows about the middle 40%), and the
// gallery's 4:5 and 2:1 placements crop landscape photos too, so a centred
// crop can drop the raft or the tents entirely. Gallery entries assume the
// placement the image's position in its gallery gives it. Unlisted images crop
// from the centre. Values are literal Tailwind classes so the scan of this
// package keeps them in the CSS. The home hero is handled separately by
// .po-hero-img in tailwind/input.css.
var imgFocus = map[string]string{
	// Full-bleed heroes and bands.
	"smith-float.jpg":     "object-[90%_50%]", // raft at the right, under the ledge
	"nfork-hero.jpg":      "object-[20%_50%]", // lit tent cabin at the left
	"fishing-alt1.jpg":    "object-[80%_50%]", // angler and bent rod at the right
	"bird-guide-dogs.jpg": "object-[70%_60%]", // guide and dogs right of centre
	"flyfishing-hero.jpg": "object-[30%_50%]", // the river's curve at the left
	"sharptail-point.jpg": "object-[88%_50%]", // the dog, facing right of centre
	// Gallery portraits (4:5) and panoramas (2:1).
	"smith-spring-wade.jpg":  "object-[75%_50%]",  // guide and raft at the right
	"smith-camp-evening.jpg": "object-[60%_50%]",  // cook at the grill
	"smith-boats-camp.jpg":   "object-[50%_75%]",  // boats along the bottom
	"nfork-tents.jpg":        "object-[80%_50%]",  // nearer tent cabin
	"yurt-wildlife.jpg":      "object-[100%_50%]", // deer at the water's edge, far right
	"sharptail-dogs.jpg":     "object-[50%_40%]",  // headroom above the dogs
	"bird-coulee.jpg":        "object-[50%_70%]",  // hunter and dog low in the coulee
}

// withFocus appends src's focal-point class, if any, to class.
func withFocus(src, class string) string {
	if f, ok := imgFocus[path.Base(src)]; ok {
		return class + " " + f
	}
	return class
}

// assetPath turns a /static/... path into its content-hashed URL (see
// internal/assets). Templates keep writing plain paths; everything that
// reaches the page goes through here.
func assetPath(p string) string {
	if logical, ok := strings.CutPrefix(p, "/static/"); ok {
		return assets.URL(logical)
	}
	return p
}

// imgVariant swaps the extension on a /static/img/foo.jpg path and returns
// its hashed URL, e.g. imgVariant("/static/img/foo.jpg", ".avif") is
// "/static/img/foo.<hash>.avif".
func imgVariant(src, ext string) string {
	if i := strings.LastIndex(src, "."); i >= 0 {
		return assetPath(src[:i] + ext)
	}
	return assetPath(src + ext)
}

// imgSrcset builds a responsive srcset of hashed URLs for the width variants
// the optimize-images pass produced: "<base>-400w.<hash><ext> 400w, …".
func imgSrcset(src, ext string) string {
	base := src
	if i := strings.LastIndex(src, "."); i >= 0 {
		base = src[:i]
	}
	parts := make([]string, 0, len(imgResponsiveWidths))
	for _, w := range imgResponsiveWidths {
		parts = append(parts, fmt.Sprintf("%s %dw", assetPath(fmt.Sprintf("%s-%dw%s", base, w, ext)), w))
	}
	return strings.Join(parts, ", ")
}
